import {COUNTRIES,BLOCS,EVENTS,PROPOSALS} from './data.js';
import {createGame,crisis,sources,availableEvents,chooseEvent,endTurn,diplomacy,projectedVotes,vote,optionReason,validateSave} from './engine.js';
import {icon,portrait,flag,map} from './visuals.js';
import {LEADER_IMAGES} from './leader-assets.js';
import {observeMaps} from './map-touch.js';
import {readPreferences,writePreferences,readSlot,writeSlot,restoreSnapshot} from './preferences.js';
import {createFeedback} from './feedback.js';
import {createSettingsViews} from './settings-ui.js';
import {platform} from './mobile-platform.js';

const SAVE='peace-committee-save-v1';
const browserStorage=platform.storage;
let preferences=readPreferences(browserStorage),preferencesNotice='',paused=true,hasSession=false;
const feedback=createFeedback(()=>preferences);
function applyPreferences(){document.documentElement.dataset.font=preferences.font;document.documentElement.dataset.press=preferences.press?'on':'off';}
function updatePreferences(patch){preferences={...preferences,...patch};try{preferences=writePreferences(browserStorage,preferences);preferencesNotice='设置已保存。';}catch{preferencesNotice='本次设置已生效，但本机未能保存。';}applyPreferences();}
applyPreferences();
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const country=id=>COUNTRIES.find(c=>c.id===id);
let state,storageWarning='';
try{const raw=browserStorage.getItem(SAVE);state=raw?validateSave(JSON.parse(raw)):createGame();hasSession=!!raw;}
catch{state=createGame();storageWarning='自动存档未能读取。可从主菜单读取其他档案，或确认开始新游戏。';}
let tab='world',layer='political',eventFilter='all',eventPage=0,proposal='observers',safeguards=true;
let modalView=null,focusBefore=null,importCandidate=null;
const compact=()=>window.innerHeight<=680;
const perPage=()=>compact()||preferences.font!=='normal'?2:3;
function save(){try{browserStorage.setItem(SAVE,JSON.stringify(state));storageWarning='';hasSession=true;return true;}catch{storageWarning='自动保存不可用，请在档案中导出存档。';return false;}}
function closeDialog(){const d=$('#dialog');modalView=null;if(d.open)d.close();}
function open(view){modalView=view;drawModal();}
function showMessage(title,message){open({type:'message',title,message});}
function commit(result){state=result.state;save();closeDialog();if(result.navigate)tab=result.navigate;if(result.proposal)proposal=result.proposal;eventPage=0;render();if(result.speaker)open({type:'speech',id:result.speaker,result,topic:result.response?'reply':'effect'});else showMessage('决定开始产生影响',result.message);}
function button(action,label,cls='primary',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;}
function pageTitle(kicker,name,extra=''){return `<div class="page-title"><div><small>${kicker}</small><h1>${name}</h1></div>${extra}</div>`;}
function pager(action,index,total,attrs=''){return `<div class="pager">${button(action,icon('chevron'),'icon-only previous',`${attrs} data-index="${index-1}" aria-label="上一页" ${index===0?'disabled':''}`)}<span><strong>${index+1}</strong> / ${Math.max(total,1)}</span>${button(action,icon('chevron'),'icon-only',`${attrs} data-index="${index+1}" aria-label="下一页" ${index>=total-1?'disabled':''}`)}</div>`;}
function header(){return `<header class="topbar"><div class="identity"><img src="./emblem.svg" alt="委员会徽记"><div><strong>世界和平委员会</strong><small>WORLD PEACE COMMITTEE</small></div></div><button class="icon-btn" data-action="settings" aria-label="打开游戏设置">${icon('settings')}</button><div class="resources">${[['spark','行动力',`${state.ap}<em>/3</em>`],['coin','预算',state.budget],['world','影响力',state.influence],['shield','公信力',state.credibility]].map(([i,label,v])=>`<div class="resource">${icon(i)}<span><small>${label}</small><strong>${v}</strong></span></div>`).join('')}</div></header><button class="crisis-strip" data-action="crisis"><span class="live-dot"></span><span>世界危机</span><strong>${crisis(state)}<small>/100</small></strong><span class="crisis-track"><i style="width:${crisis(state)}%"></i></span><span class="crisis-state">${crisis(state)===0?'和平已达成':crisis(state)>=70?'局势危急':crisis(state)>=40?'局势紧张':'正在缓和'}</span>${icon('chevron')}</button>`;}
function navigation(){return `<nav class="navigation" aria-label="主要页面">${[['world','世界'],['events','事件'],['council','议会'],['committee','委员会']].map(([id,name])=>`<button class="nav-item ${tab===id?'active':''}" data-action="tab" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span>${id==='events'&&availableEvents(state).length?`<i>${availableEvents(state).length}</i>`:''}</button>`).join('')}</nav>`;}
function turnBar(){return `<div class="turn-bar"><div><strong>${state.status==='playing'?`第 ${String(state.turn).padStart(2,'0')} 回合 · 剩余 ${state.ap} 次行动`:state.status==='won'?'和平已达成':'任期已结束'}</strong><small>${state.status==='playing'?`${state.projects.length} 项工作等待结算`:'查看本届任期的结果'}</small></div>${button(state.status==='playing'?'end':'ending',`${state.status==='playing'?'结束回合':'查看结果'} ${icon('arrow')}`)}</div>`;}
function world(){const focus=availableEvents(state)[0];return `<section class="screen world-screen">${pageTitle('CHARTER YEAR 06','镜河之争',`<span class="cycle">${String(state.turn).padStart(2,'0')}<small>/24</small></span>`)}${map(state,layer)}${focus?`<button class="focus-brief" data-action="event" data-id="${focus.id}"><div class="focus-symbol">${portrait(country(focus.speaker))}</div><div><small>本期重点 · ${focus.kind}</small><h2>${focus.title}</h2><p>${country(focus.speaker).leader}已提交一份外交简报</p></div>${icon('arrow')}</button>`:`<div class="focus-brief quiet">${icon('check')}<div><h2>本期简报已处理</h2><p>继续开展外交，或推进回合。</p></div></div>`}<div class="quick-actions">${button('roster',`${icon('world')} 七国外交`,'secondary')}${button('collection',`${icon('clock')} 执行项目 <b>${state.projects.length}</b>`,'secondary','data-kind="projects"')}</div></section>`;}
function filteredEvents(){let events=availableEvents(state);if(eventFilter==='random')events=events.filter(e=>e.random);if(eventFilter==='urgent')events=events.filter(e=>e.id.startsWith('SEC')||e.id.startsWith('HUM'));if(eventFilter==='build')events=events.filter(e=>e.id.startsWith('END')||e.id==='MIR-04');return events;}
function eventsPage(){const events=filteredEvents(),count=perPage(),total=Math.max(1,Math.ceil(events.length/count));eventPage=Math.min(eventPage,total-1);return `<section class="screen events-screen">${pageTitle('INTELLIGENCE','待审议事件',`<span class="count-badge">${events.length} 份简报</span>`)}<div class="segmented filters">${[['all','全部'],['random','随机来函'],['urgent','安全'],['build','建设']].map(([id,label])=>`<button data-action="filter" data-filter="${id}" class="${eventFilter===id?'selected':''}" aria-pressed="${eventFilter===id}">${label}</button>`).join('')}</div><div class="event-list" style="--rows:${Math.min(count,Math.max(events.length,1))}">${events.slice(eventPage*count,(eventPage+1)*count).map(e=>`<button class="event-card" data-action="event" data-id="${e.id}"><img class="event-portrait" src="${LEADER_IMAGES[e.speaker]}" alt="" aria-hidden="true"><div class="card-meta"><span>${e.kind}</span><small>${e.random?'第 '+state.randomEvents.pending.find(p=>p.id===e.id).deadline+' 回合截止':e.id}</small></div><h2>${e.title}</h2><p>${e.text}</p><div class="card-bottom"><span>${e.countries.map(id=>flag(country(id))).join('')}</span><strong>打开简报 ${icon('arrow')}</strong></div></button>`).join('')||`<div class="empty-state">${icon('check')}<h2>暂无此类待办</h2><p>可以切换分类，或继续开展外交。</p></div>`}</div><div class="screen-bottom"><span>逐份处理，让每次选择有分量。</span>${pager('event-page',eventPage,total)}</div></section>`;}
function council(){const p=PROPOSALS.find(x=>x.id===proposal),votes=projectedVotes(state,proposal,safeguards),yes=votes.filter(v=>v.vote==='yes').length,needed=p.type==='major'?5:4,passed=state.passed.includes(p.id);return `<section class="screen council-screen">${pageTitle('GENERAL ASSEMBLY','七国议会','<span class="count-badge">一国一票</span>')}<label class="proposal-select"><span>当前议案</span><select id="proposal-select">${PROPOSALS.map(x=>`<option value="${x.id}" ${x.id===proposal?'selected':''}>${x.title}</option>`).join('')}</select></label><button class="proposal-brief" data-action="proposal-details"><div><span class="tag">${p.type==='major'?'重大议案':'普通议案'} · 至少 ${needed} 票</span><p>${p.desc}</p><small>执行预算 ${p.cost} · 表决消耗 1 行动力</small></div>${icon('chevron')}</button><div class="seat-heading"><strong>当前票态</strong><small>点击代表开展外交</small></div><div class="seat-grid">${votes.map(v=>{const c=country(v.id);return `<button class="seat ${v.vote}" data-action="country" data-id="${c.id}">${portrait(c)}<strong>${c.short}</strong><span>${{yes:'赞成',no:'反对',abstain:'弃权'}[v.vote]}</span></button>`;}).join('')}<button class="seat seat-rules" data-action="proposal-details">${icon('council')}<strong>议案条款</strong><span>查看与调整</span></button></div><div class="vote-bar"><div><strong>${yes}<small>/ ${needed}</small></strong><span>预计赞成</span></div>${button('vote',passed?'已经通过':state.votesThisTurn?'本回合已表决':'提交表决','primary',passed||state.votesThisTurn||state.ap<1||state.status!=='playing'?'disabled':'')}</div><p class="screen-note">弃权不降低门槛；通过后仍需准入与执行条件。</p></section>`;}
function committee(){const values=state.trajectory,points=values.map((v,i)=>`${15+i*330/Math.max(values.length-1,1)},${82-v*.65}`).join(' ');return `<section class="screen committee-screen">${pageTitle('YOUR MANDATE','委员会事务',`<button class="icon-btn" data-action="archive" aria-label="存档与新任期">${icon('file')}</button>`)}<button class="trajectory-card" data-action="crisis"><div><span>危机轨迹</span><strong>46 ${icon('arrow')} ${crisis(state)}</strong></div><svg viewBox="0 0 360 100" aria-label="危机值轨迹"><path d="M15 25H345M15 55H345M15 85H345" stroke="#ffffff0a"/><polyline points="${points}" fill="none" stroke="#bfd0aa" stroke-width="2.5"/>${values.map((v,i)=>`<circle cx="${15+i*330/Math.max(values.length-1,1)}" cy="${82-v*.65}" r="3" fill="#bfd0aa"/>`).join('')}</svg><small>点击查看每一项危机来源</small></button><div class="office-grid">${[['projects','clock','执行项目',state.projects.length,'进度与维护费用'],['promises','shield','履约清单',state.promises.filter(p=>!p.fulfilled&&!p.broken).length,'承诺与到期情况'],['history','events','外交纪事',state.history.length,'每次决定的回响'],['archive','file','任期档案','↗','存档、恢复与新任期']].map(([kind,i,label,n,detail])=>`<button data-action="${kind==='archive'?'archive':'collection'}" data-kind="${kind}" class="office-card">${icon(i)}<b>${n}</b><strong>${label}</strong><small>${detail}</small></button>`).join('')}</div><button class="latest-note" data-action="collection" data-kind="history"><small>最近动态 ${icon('chevron')}</small><strong>${esc(state.history[0]?.title||'任期开始')}</strong><p>${esc(state.history[0]?.text||'')}</p></button><div class="save-status">${icon(storageWarning?'help':'check')} ${storageWarning?'自动保存需关注，点击档案查看':'本机自动保存 · 世界种子 '+state.seed}</div></section>`;}
function render(){if(paused){$('#app').innerHTML=settingsViews.titleScreen();observeMaps();return;}const content={world,events:eventsPage,council,committee}[tab]();$('#app').innerHTML=`<div class="app-shell">${header()}<main>${content}</main>${turnBar()}${navigation()}</div>`;observeMaps();}

function modalHead(kicker,title,subtitle=''){return `<header class="modal-head"><small>${kicker}</small><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</header>`;}
function modalFoot(left,right){return `<footer class="modal-foot">${left}${right}</footer>`;}
function dialogLayout(head,body,foot,cls=''){return `<button class="dialog-close icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button><div class="modal-shell ${cls}">${head}<div class="modal-body">${body}</div>${foot}</div>`;}
function costText(o){return `${o.ap?o.ap+' 行动力':'不耗行动力'}${o.budget?' · 预算 '+o.budget:''}${o.influence?' · 影响力 '+o.influence:''}`;}
function speechView(v){const e=v.event?EVENTS.find(x=>x.id===v.event):null,c=country(e?.speaker||v.id),topic=v.topic||(v.result?'effect':'quote'),pending=e?.random?state.randomEvents.pending.find(p=>p.id===e.id):null;
 const topics=v.result?[...(v.result.response?[['reply','领导人回应',v.result.response]]:[]),['effect','执行反馈',v.result.message+(v.result.changes?' '+v.result.changes:'')]]:[['quote','当前观点',e?.quote||c.quote],['need','追问诉求',e?.dialogue?.need||c.goal],['line','确认底线',e?.dialogue?.line||c.line]];
 const current=topics.find(t=>t[0]===topic)||topics[0],text=current[2],chunkSize=preferences.font==='normal'?80:compact()?44:60,pages=Array.from(text.matchAll(new RegExp('[\\s\\S]{1,'+chunkSize+'}','g')),m=>m[0]),page=Math.min(v.page||0,pages.length-1);
 const label=v.result?'决定后的回应':e?e.title:'双边会见';
 const back=v.result?button('close','返回局势','secondary'):e?button('event-background','事件背景','secondary',`data-id="${e.id}"`):button('country','开展外交','secondary',`data-id="${c.id}"`);
 const next=v.result?(topics.length>1?button('speech-topic',topic==='effect'?'听取回应':'查看实际影响','primary',`data-topic="${topic==='effect'?'reply':'effect'}"`):button('close','知道了')):e?button('event-choices','比较回应方案','primary',`data-id="${e.id}"`):button('close','结束会见');
 return dialogLayout(modalHead(e?.random?`${e.kind} · 第 ${pending?.deadline} 回合结束前答复`:'DIPLOMATIC DIALOGUE',label),`<div class="speech-stage" style="--speaker-color:${c.color}"><span class="speech-nation">${flag(c)} ${c.name}</span><img class="leader-bust" src="${LEADER_IMAGES[c.id]}" alt="${c.leader}半身立绘" width="1024" height="1536"><span class="speech-trust">信任 ${state.countries[c.id].trust}</span></div><div class="speech-copy"><div class="speech-name"><strong>${c.leader}</strong><small>${c.role} · ${current[1]}</small></div><p aria-live="polite">${esc(pages[page])}</p>${pages.length>1?pager('speech-page',page,pages.length):''}</div><div class="speech-topics">${topics.map(([id,label])=>button('speech-topic',label,topic===id?'primary':'secondary',`data-topic="${id}" aria-pressed="${topic===id}"`)).join('')}</div>`,modalFoot(back,next),'speech-dialog');
}
function eventView(v){const e=EVENTS.find(x=>x.id===v.id),c=country(e.speaker),step=v.step||'speech';
 if(step==='speech')return speechView({...v,event:e.id});
 if(step==='brief')return dialogLayout(modalHead(`${e.kind} / 01 · 简报`,e.title),`<div class="speaker-block">${portrait(c)}<div><strong>${c.leader}<small>${c.role} · ${c.short}</small></strong><blockquote>“${e.quote}”</blockquote></div></div><p class="narrative">${e.text}</p>${e.random?`<div class="info-note">${esc(state.randomEvents.pending.find(p=>p.id===e.id)?.cause?'前因：'+state.randomEvents.pending.find(p=>p.id===e.id).cause+'。':'本次来函由当前局势与世界种子共同产生。')}请在第 ${state.randomEvents.pending.find(p=>p.id===e.id)?.deadline} 回合结束前答复，逾期发言国信任 -2。</div>`:''}<div class="related-nations"><small>相关国家</small><div>${e.countries.map(id=>`<button class="country-pill" data-action="country" data-id="${id}">${flag(country(id))}${country(id).short}</button>`).join('')}</div></div><div class="info-note">阅读不消耗行动力。下一步比较回应方案，再确认投入。</div>`,modalFoot(button('event','听取发言','secondary',`data-id="${e.id}"`),button('event-choices',`比较 4 种回应 ${icon('arrow')}`,'primary',`data-id="${e.id}"`)),'event-brief');
 if(step==='choices')return dialogLayout(modalHead(`${e.kind} / 02 · 回应`,e.title,'选择方案后查看完整效果与执行条件。'),`<div class="option-list">${e.options.map((o,i)=>{const reason=optionReason(state,o);return `<button class="option-summary ${reason?'restricted':''}" data-action="select-option" data-event="${e.id}" data-option="${o.id}"><span class="option-letter">${'ABCD'[i]}</span><div><strong>${o.title}</strong><small>${reason?'条件未满足 · 点击查看':costText(o)}</small></div>${icon('chevron')}</button>`;}).join('')}</div><div class="info-note">“暂不介入”会保存行动力，但不会停止世界变化。</div>`,modalFoot(button('event','返回简报','secondary',`data-id="${e.id}"`),'<span class="step-counter">2 / 3</span>'),'event-choices');
 const o=e.options.find(x=>x.id===v.option),reason=optionReason(state,o);
 return dialogLayout(modalHead(`${e.title} / 03 · 确认`,o.title),`<div class="decision-cost"><small>即时代价</small><strong>${costText(o)}</strong></div><section class="decision-detail"><small>预计影响与执行条件</small><p>${o.detail}</p></section>${reason?`<div class="condition-warning">${icon('help')}<div><strong>暂时无法执行</strong><p>${reason}</p></div></div>`:'<div class="info-note">各国会根据利益和已有承诺回应。确认后立即扣除已列出的行动成本。</div>'}<div class="remaining-resources"><span>行动力 <b>${state.ap}</b></span><span>预算 <b>${state.budget}</b></span><span>影响力 <b>${state.influence}</b></span></div>`,modalFoot(button('event-choices','换一个方案','secondary',`data-id="${e.id}"`),button('confirm-option','确认决策','primary',`id="confirm-choice" data-event="${e.id}" data-option="${o.id}" ${reason?'disabled':''}`)),'event-confirm');
}
function diplomacyReason(id,mode){return state.status!=='playing'?'任期已结束':state.lobbied[`${id}-${mode}`]?'本回合已开展':state.ap<1?'行动力不足':mode==='fund'&&state.countries[id].trust<60?'需要信任达到 60':mode==='aid'&&state.budget<4?'预算不足':mode!=='aid'&&state.influence<(mode==='fund'?3:2)?'影响力不足':'';}
function mapView(){return dialogLayout(modalHead('ILAN / DIPLOMACY','七国外交地图'),`${map(state,layer,true)}`,modalFoot('<span>点击国名或领土，查看外交与诉求。</span>',button('roster','国家列表','secondary')),'map-dialog');}
function countryView(v){const c=country(v.id),section=v.section||'diplomacy',t=state.countries[c.id].trust;return dialogLayout(modalHead(BLOCS[c.bloc],c.name),`<div class="country-profile">${portrait(c)}<div><strong>${c.leader}</strong><small>${c.role}</small><span>对委员会信任 <b>${t}</b><em>/100</em></span></div></div><div class="segmented modal-tabs">${[['diplomacy','双边外交'],['profile','诉求与底线'],['vote','议会立场']].map(([id,name])=>`<button data-action="country-section" data-id="${c.id}" data-section="${id}" class="${section===id?'selected':''}">${name}</button>`).join('')}</div>${section==='profile'?`<div class="profile-facts">${[['当前诉求',c.goal],['外交底线',c.line],['合作筹码',c.offer]].map(([h,p])=>`<section><small>${h}</small><p>${p}</p></section>`).join('')}</div>`:section==='vote'?(()=>{const p=PROPOSALS.find(x=>x.id===proposal),a=projectedVotes(state,proposal,safeguards).find(x=>x.id===c.id);return `<div class="position-card"><small>${p.title}</small><strong class="${a.vote}">${{yes:'预计赞成',no:'预计反对',abstain:'预计弃权'}[a.vote]}</strong><p>${a.reason}</p><div class="info-note">改善关系能改变谈判条件，但不保证无条件支持。</div></div>`;})():`<div class="diplomacy-options">${[['talk','交换诉求','信任 +10','1 行动力 · 2 影响力'],['aid','专项民生援助','信任 +14','1 行动力 · 4 预算'],['fund','争取公开拨款','预算 +7，信任 -5','1 行动力 · 3 影响力']].map(([mode,label,gain,cost])=>{const reason=diplomacyReason(c.id,mode);return `<button class="diplomacy-action" data-action="diplomacy" data-id="${c.id}" data-mode="${mode}" ${reason?'disabled':''}><div><strong>${label}</strong><small>${reason||cost}</small></div><span>${gain.split('，').map(item=>`<span class="diplomacy-gain">${item}</span>`).join('')}</span></button>`;}).join('')}</div>`}`,modalFoot(button('roster','全部国家','secondary'),button('leader-talk','听取发言','primary',`data-id="${c.id}"`)),'country-dialog');}
function rosterView(){return dialogLayout(modalHead('DIPLOMATIC DIRECTORY','七国代表'),`<div class="roster">${COUNTRIES.map(c=>`<button data-action="country" data-id="${c.id}">${flag(c)}<div><strong>${c.short}<small>${c.leader}</small></strong><span>${c.resource}</span></div><b>${state.countries[c.id].trust}</b>${icon('chevron')}</button>`).join('')}</div>`,modalFoot('<span>右侧数值为对委员会的信任</span>',button('close','返回地图')),'roster-dialog');}
const listLabels={projects:'执行项目',promises:'履约清单',history:'外交纪事',crisis:'危机来源'};
function collectionView(v){const kind=v.kind,index=Math.max(0,v.index||0),items=kind==='crisis'?sources(state):state[kind];const i=Math.min(index,Math.max(0,items.length-1));v.index=i;const item=items[i];let body;
 if(!item)body=`<div class="empty-state">${icon('check')}<h3>${kind==='crisis'?'当前危机已全部关闭':'这里暂时没有记录'}</h3><p>${kind==='crisis'?'下次结算时将检查胜利。':'后续工作会自动记录在这里。'}</p></div>`;
 else if(kind==='projects')body=`<article class="detail-entry"><span class="entry-symbol">${icon('clock')}</span><h3>${esc(item.name)}</h3><div class="large-metric">${item.remaining}<small>次结算后完成</small></div><p>${item.maintenance?'每次结算需要预算 '+item.maintenance:'没有额外维护费用。'}</p><div class="info-note">项目在回合结束时推进。预算不足或执行条件未满足时会暂停，并在报告中说明。</div></article>`;
 else if(kind==='promises')body=`<article class="detail-entry"><span class="tag">${item.fulfilled?'已兑现':item.broken?'已逾期':'等待履行'}</span><h3>${esc(item.name)}</h3><p>约定期限：第 ${item.due} 回合结束前。</p><div class="info-note">${item.fulfilled?'履约已经记录在国家关系与公信力中。':item.broken?'逾期后仍可完成工作，修复关系。':'请为执行预留时间，只有实际完成才算履约。'}</div></article>`;
 else if(kind==='history')body=`<article class="detail-entry ${item.tone}"><span class="tag">第 ${String(item.turn).padStart(2,'0')} 回合</span><h3>${esc(item.title)}</h3><p class="entry-text">${esc(item.text)}</p></article>`;
 else body=`<article class="detail-entry"><span class="tag">当前独立计分来源</span><h3>${item.name}</h3><div class="large-metric danger-text">+${item.value}<small>世界危机</small></div><p>${item.help}</p><div class="info-note">关闭具体来源才能降低危机。临时缓解不会掩盖未解决的长期风险。</div></article>`;
 return dialogLayout(modalHead(kind==='crisis'?`世界危机 ${crisis(state)} / 100`:'COMMITTEE RECORD',listLabels[kind],items.length?`共 ${items.length} 项 · 逐项查看`:''),body,modalFoot(pager('collection-page',i,items.length,`data-kind="${kind}"`),button('close','返回')),'collection-dialog');
}
function proposalView(){const p=PROPOSALS.find(x=>x.id===proposal);return dialogLayout(modalHead('ASSEMBLY / 议案条款',p.title),`<span class="tag">${p.type==='major'?'重大议案 · 至少 5 票':'普通议案 · 至少 4 票'}</span><p class="narrative">${p.desc}</p><label class="checkbox-row"><input type="checkbox" id="safeguards" ${safeguards?'checked':''}><span><strong>加入期限、监督与民用保障</strong><small>减少模糊授权，提高程序可信度。调整后七国会重新评估立场。</small></span></label><div class="decision-cost"><small>表决与执行</small><strong>1 行动力 · 执行预算 ${p.cost}</strong></div><div class="info-note">弃权不降低门槛。未通过不扣执行预算；授权通过也不等于自动完成部署。</div>`,modalFoot(button('close','返回议会'),'<span>变更即时反映到票态</span>'),'proposal-dialog');}
function voteView(v){const r=v.result;return dialogLayout(modalHead('ASSEMBLY RESULT',r.passed?'议案获得通过':'议案未获通过'),`<p class="narrative">${esc(r.message)}</p><div class="vote-results">${r.votes.map(x=>`<div>${flag(country(x.id))}<span>${country(x.id).short}</span><strong class="${x.vote}">${{yes:'赞成',no:'反对',abstain:'弃权'}[x.vote]}</strong></div>`).join('')}</div>`,modalFoot('<span>执行结果已记入外交纪事</span>',button('close','返回议会')),'vote-dialog');}
const guide=[['读懂局势','目标是在 24 回合内让危机值降至 0。点击地图国家查看诉求，点击危机条查看问题来源，阅读不消耗行动力。'],['选择回应','每回合 3 点行动力。先听取领导人观点，可免费追问诉求与底线，再比较方案并确认。随机来函有期限，部分选择会引出后续事件。'],['改变第三国的立场','可以先帮助曜沙、澄海或岚原，改变赤峰与丰谷的谈判条件。国家根据利益和信任回应，不会无条件服从。'],['取得议会授权','七国各一票。普通议案需要 4 票，重大议案需要 5 票。点击代表开展外交，点击议案查看条款。'],['兑现并复盘','结束回合推进项目，补充预算 6、影响力 3。结算报告逐项展示变化。预算不足可向信任达到 60 的国家争取拨款。'],['建立持续的和平','停止冲突之外，还需供水、贸易和长期履约。危机到 100、任期到期未完成，或公信力连续 3 回合低于 15，均会失败。']];
function helpView(v){const i=v.index||0,[h,p]=guide[i];return dialogLayout(modalHead(`主席手册 / ${i+1} OF ${guide.length}`,h),`<div class="guide-art">${icon(['world','events','shield','council','clock','check'][i])}</div><p class="narrative guide-copy">${p}</p><div class="info-note">所有页面均可在一屏内操作。更多信息通过弹窗与翻页查看。</div>`,modalFoot(pager('guide-page',i,guide.length),button('close',paused?'返回主菜单':'返回游戏')),'guide-dialog');}
function endView(){return dialogLayout(modalHead(`END OF CYCLE ${state.turn}`,'让世界作出回应'),`<p class="narrative">${state.ap?`你还有 ${state.ap} 点行动力，结束后不会累积。`:'本回合行动力已经用尽。'}各国将回应你的决定，执行项目与承诺会进行结算。</p><div class="metric-grid"><div><span>当前危机</span><strong>${crisis(state)}</strong></div><div><span>执行项目</span><strong>${state.projects.length}</strong></div><div><span>下回合预算</span><strong>+6</strong></div></div>${button('collection','查看正在执行的工作','secondary wide','data-kind="projects"')}<div class="info-note">既有风险不会因暂不介入而暂停。新的变化会在结算报告中说明。</div>`,modalFoot(button('close','继续安排','secondary'),button('confirm-end','确认结束回合')),'end-dialog');}
function reportView(v){const r=state.lastReport;if(!r)return messageView({title:'暂无结算报告',message:'请先完成一个回合。'});const i=Math.min(v.index||0,r.entries.length),h=r.entries[i-1];return dialogLayout(modalHead(`第 ${r.turn} 回合结算 / ${i===0?'总览':'动态 '+i}`,i===0?'世界正在回应你':esc(h.title)),i===0?`<div class="report-crisis"><span>${r.before}</span>${icon('arrow')}<strong class="${r.after<=r.before?'good-text':'danger-text'}">${r.after}</strong></div><p class="narrative">${r.entries.length?`本次有 ${r.entries.length} 项新变化。使用下方翻页按钮逐项查看。`:'本次没有新增突发变化，既有工作继续推进。'}</p><div class="metric-grid"><div><span>行动力恢复</span><strong>3</strong></div><div><span>预算增加</span><strong>+6</strong></div><div><span>影响力增加</span><strong>+3</strong></div></div>`:`<article class="detail-entry ${h.tone}"><span class="tag">第 ${h.turn} 回合</span><p class="entry-text">${esc(h.text)}</p><div class="info-note">本条记录已保存在外交纪事中，可随时回看。</div></article>`,modalFoot(pager('report-page',i,r.entries.length+1),button('close',`进入第 ${state.turn} 回合`)),'report-dialog');}
function endingView(){const won=state.status==='won';return dialogLayout(modalHead('END OF MANDATE',esc(state.ending)),`<div class="guide-art">${icon(won?'world':'flag')}</div><p class="narrative">${won?'当前危机来源全部关闭。七国仍有分歧，但和平已经拥有可以执行的安排。':'未解决的问题与每次选择都保存在外交纪事中。下一届任期可以尝试另一条路线。'}</p><div class="metric-grid"><div><span>最终危机</span><strong>${crisis(state)}</strong></div><div><span>决策次数</span><strong>${state.actionCount}</strong></div><div><span>公信力</span><strong>${state.credibility}</strong></div></div>`,modalFoot(button('review','查看纪事','secondary'),button('new','新的任期')),'ending-dialog');}
function archiveView(){return dialogLayout(modalHead('MANDATE ARCHIVE','任期档案'),`<div class="archive-status">${icon(storageWarning?'help':'check')}<p>${storageWarning||'每次确认行动后自动保存到本机。导出档案，可以在其他设备继续。'}</p></div><div class="archive-actions">${button('export',`${icon('download')} 导出存档`,'secondary')}${button('import',`${icon('file')} 导入存档`,'secondary')}${button('settings','手动存档与读档','secondary','data-section="slots"')}${button('new',`${icon('reset')} 开始新任期`,'secondary')}</div><div class="info-note">世界种子 ${state.seed}<br>第 ${state.turn} 回合 · ${state.actionCount} 次决策</div>`,modalFoot('<span>重开前可先导出当前档案</span>',button('close','返回')),'archive-dialog');}
function newView(v){return dialogLayout(modalHead('A NEW MANDATE','开始新的游戏'),`<p class="narrative">${hasSession?'新游戏将替换自动存档。确认后，当前任期会保留在“备份”档位，也可以先导出文件。':storageWarning?'原自动存档无法读取。确认开始将替换它；也可以返回主菜单读取其他档案。':'镜河水位下降，七国各有立场。你将主持和平委员会，通过外交与议会把世界危机降为零。'}</p><label class="seed-label" for="seed-input">世界种子</label><input class="seed-input" id="seed-input" type="number" inputmode="numeric" min="1" max="4294967295" value="${esc(v.seed??state.seed)}">${button('shuffle-seed','换一个世界种子','secondary wide')}<div class="info-note">相同种子与决策顺序产生相同结果。七国身份和镜河主线根源保持不变。</div>`,modalFoot(hasSession?button('export','先导出存档','secondary'):button('close','返回主菜单','secondary'),button('confirm-new','确认开始')),'new-dialog');}
function messageView(v){return dialogLayout(modalHead(v.error?'需要调整安排':'DECISION / 世界回应',esc(v.title)),`<div class="guide-art">${icon(v.error?'help':'check')}</div><p class="narrative message-copy">${esc(v.message)}</p>`,modalFoot('<span>可在外交纪事中回看已确认决定</span>',button('close',paused?'返回主菜单':'返回局势')),'message-dialog');}
function importView(){return dialogLayout(modalHead('RESTORE MANDATE',`恢复第 ${importCandidate.turn} 回合？`),`<p class="narrative">读取后将回到这个时间点。当前进度会保存在“备份”档位，方便返回。</p><div class="metric-grid"><div><span>当前危机</span><strong>${crisis(importCandidate)}</strong></div><div><span>公信力</span><strong>${importCandidate.credibility}</strong></div><div><span>行动力</span><strong>${importCandidate.ap}</strong></div></div><div class="info-note">世界种子 ${importCandidate.seed}</div>`,modalFoot(button('close','取消','secondary'),button('confirm-import','确认恢复')),'import-dialog');}
function drawModal(){if(!modalView)return;const d=$('#dialog'),v=modalView,oldPortrait=d.open?d.querySelector('.leader-bust')?.alt:null,focused=d.contains(document.activeElement)?document.activeElement:null,oldAction=focused?.dataset.action,oldTopic=focused?.dataset.topic;const renderers={settings:settingsViews.settingsView,slotConfirm:settingsViews.slotConfirmView,exit:settingsViews.exitView,map:mapView,speech:speechView,event:eventView,country:countryView,roster:rosterView,collection:collectionView,proposal:proposalView,vote:voteView,help:helpView,end:endView,report:reportView,ending:endingView,archive:archiveView,new:newView,message:messageView,import:importView};if(!d.open)focusBefore=document.activeElement;d.innerHTML=renderers[v.type](v);d.dataset.type=v.type;if(!d.open)d.showModal();const newPortrait=d.querySelector('.leader-bust');if(newPortrait&&newPortrait.alt===oldPortrait)newPortrait.style.animation='none';const keepFocus=oldAction==='speech-topic'&&oldTopic?d.querySelector('[data-action="speech-topic"][data-topic="'+oldTopic+'"]'):null;(keepFocus||d.querySelector('.dialog-close')).focus({preventScroll:true});observeMaps();}
function exportSave(){if(!hasSession)return;const text=JSON.stringify(state,null,2),name=`世界和平委员会-${state.seed}-第${state.turn}回合.json`;if(platform.native){platform.exportFile(name,text);return;}const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

const settingsViews=createSettingsViews({button,dialogLayout,modalHead,modalFoot,esc,getState:()=>state,getPreferences:()=>preferences,getWarning:()=>storageWarning,getNotice:()=>preferencesNotice,getSlot:id=>readSlot(browserStorage,id),isPaused:()=>paused,hasSession:()=>hasSession,isNative:()=>platform.native,canVibrate:()=>platform.canVibrate()});
function storeManualSlot(id){if(!hasSession)return;writeSlot(browserStorage,id,state);open({type:'settings',section:'slots',slot:id,notice:'已保存到存档 '+id+'。'});}
function restoreImported(){const next=restoreSnapshot(browserStorage,importCandidate,hasSession?state:null);state=next;importCandidate=null;storageWarning='';hasSession=true;paused=false;closeDialog();tab='world';eventPage=0;render();}
document.addEventListener('visibilitychange',()=>{if(document.hidden)feedback.suspend();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;if(!['mute','preview-sound','confirm-exit'].includes(b.dataset.action))feedback.press();try{switch(b.dataset.action){
case 'settings':open({type:'settings',section:b.dataset.section||'preferences',slot:b.dataset.slot||'1'});break;
case 'font-size':updatePreferences({font:b.dataset.font});eventPage=0;render();drawModal();break;
case 'mute':updatePreferences({muted:!preferences.muted});drawModal();break;
case 'preview-sound':feedback.preview().then(played=>{const out=$('#preference-status');if(out)out.textContent=played?'已播放提示音。':preferences.muted||!preferences.volume?'当前已静音，请先开启音量。':'本机未能播放声音。';});break;
case 'slot-save':{const id=b.dataset.slot,entry=readSlot(browserStorage,id);if(entry.kind==='empty')storeManualSlot(id);else open({type:'slotConfirm',slot:id});break;}
case 'confirm-slot-save':storeManualSlot(b.dataset.slot);break;
case 'slot-load':{const entry=readSlot(browserStorage,b.dataset.slot);if(entry.kind!=='valid')throw Error('此档案无法读取，请选择其他存档。');importCandidate=entry.state;open({type:'import'});break;}
case 'exit':open({type:'exit'});break;
case 'confirm-exit':if(!save())throw Error('当前进度未能保存。请返回设置，先导出存档文件。');paused=true;feedback.suspend();closeDialog();render();break;
case 'resume':if(!hasSession)return;paused=false;closeDialog();render();break;
case 'tab':tab=b.dataset.tab;closeDialog();render();break;
case 'map':open({type:'map'});break;
case 'layer':layer=b.dataset.layer;render();if(modalView?.type==='map')drawModal();break;
case 'filter':eventFilter=b.dataset.filter;eventPage=0;render();break;
case 'event-page':eventPage=Number(b.dataset.index);render();break;
case 'event':open({type:'event',id:b.dataset.id,step:'speech'});break;
case 'event-background':open({type:'event',id:b.dataset.id,step:'brief'});break;
case 'speech-topic':open({...modalView,topic:b.dataset.topic,page:0});break;
case 'speech-page':open({...modalView,page:Number(b.dataset.index)});break;
case 'leader-talk':open({type:'speech',id:b.dataset.id});break;
case 'event-choices':open({type:'event',id:b.dataset.id,step:'choices'});break;
case 'select-option':open({type:'event',id:b.dataset.event,step:'confirm',option:b.dataset.option});break;
case 'confirm-option':commit(chooseEvent(state,b.dataset.event,b.dataset.option));break;
case 'country':open({type:'country',id:b.dataset.id});break;
case 'country-section':open({type:'country',id:b.dataset.id,section:b.dataset.section});break;
case 'roster':open({type:'roster'});break;
case 'diplomacy':commit(diplomacy(state,b.dataset.id,b.dataset.mode));break;
case 'crisis':open({type:'collection',kind:'crisis',index:0});break;
case 'collection':open({type:'collection',kind:b.dataset.kind,index:0});break;
case 'collection-page':open({type:'collection',kind:b.dataset.kind,index:Number(b.dataset.index)});break;
case 'proposal-details':open({type:'proposal'});break;
case 'vote':{const result=vote(state,proposal,safeguards);state=result.state;save();render();open({type:'vote',result});break;}
case 'help':open({type:'help',index:0});break;
case 'guide-page':open({type:'help',index:Number(b.dataset.index)});break;
case 'end':open({type:'end'});break;
case 'confirm-end':state=endTurn(state).state;save();render();open(state.status==='playing'?{type:'report',index:0}:{type:'ending'});break;
case 'report-page':open({type:'report',index:Number(b.dataset.index)});break;
case 'ending':open({type:'ending'});break;
case 'review':tab='committee';render();open({type:'collection',kind:'history',index:0});break;
case 'archive':open({type:'archive'});break;
case 'new':open({type:'new'});break;
case 'shuffle-seed':{const n=crypto.getRandomValues(new Uint32Array(1))[0]||1;modalView.seed=n;$('#seed-input').value=n;break;}
case 'confirm-new':{const n=Number($('#seed-input').value);if(!Number.isInteger(n)||n<1||n>4294967295)throw new Error('请输入 1 至 4294967295 之间的整数种子。');const next=restoreSnapshot(browserStorage,createGame(n),hasSession?state:null);state=next;hasSession=true;storageWarning='';paused=false;tab='world';eventPage=0;closeDialog();render();break;}
case 'export':exportSave();break;
case 'import':if(platform.native)platform.importFile();else $('#import-save').click();break;
case 'confirm-import':restoreImported();break;
case 'close':closeDialog();break;
}}catch(error){open({type:'message',title:'这项安排暂时无法执行',message:error.message,error:true});}});
document.addEventListener('input',e=>{if(e.target.id==='settings-volume'){updatePreferences({volume:Number(e.target.value),muted:false});$('#volume-value').textContent=preferences.volume+'%';$('#preference-status').textContent=preferencesNotice;const mute=$('[data-action="mute"]');if(mute){mute.textContent='静音';mute.setAttribute('aria-pressed','false');}}if(e.target.id==='seed-input'&&modalView?.type==='new')modalView.seed=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='settings-volume'){void feedback.preview();}if(e.target.id==='settings-press'||e.target.id==='settings-vibration'){updatePreferences({[e.target.id==='settings-press'?'press':'vibration']:e.target.checked});$('#preference-status').textContent=preferencesNotice;}if(e.target.id==='proposal-select'){proposal=e.target.value;render();}if(e.target.id==='safeguards'){safeguards=e.target.checked;render();}});
document.addEventListener('keydown',e=>{const target=e.target.closest('[data-action]');if(target?.tagName.toLowerCase()==='g'&&(e.key==='Enter'||e.key===' ')){e.preventDefault();target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('#dialog').addEventListener('cancel',()=>{modalView=null;});
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open){modalView=null;if(focusBefore?.isConnected)focusBefore.focus({preventScroll:true});}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#import-save').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500000)throw new Error('存档文件过大。');importCandidate=validateSave(JSON.parse(await file.text()));open({type:'import'});}catch(error){open({type:'message',title:'无法恢复这份档案',message:error.message,error:true});}finally{e.target.value='';}});
let previousCompact=compact(),resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(previousCompact!==compact()){previousCompact=compact();eventPage=0;render();}if(modalView)drawModal();},120);});
// Android invokes these only for its bundled page. Import still requires confirmation.
window.PeaceMobile={
 back(){if($('#dialog').open){closeDialog();return;}if(paused)platform.requestExit();else open({type:'exit'});},
 pause(){feedback.suspend();if(hasSession&&!paused)save();},
 receive(kind,text){
  if(kind==='import'){try{if(new TextEncoder().encode(text).length>500000)throw Error('存档文件过大。');importCandidate=validateSave(JSON.parse(text));open({type:'import'});}catch(error){open({type:'message',title:'无法恢复这份档案',message:error.message,error:true});}}
  else showMessage(kind==='error'?'文件操作未完成':'档案提示',text);
 }
};
render();observeMaps();if(storageWarning)showMessage('档案读取提示',storageWarning);platform.ready();
